/** Size class of a Turn by its estimated tokens, smallest first. */
export type Bucket = "tiny" | "small" | "medium" | "large" | "huge";

/**
 * Exclusive upper bound of each bounded bucket, ascending; lower bounds are
 * inclusive and equal to the previous bucket's upper bound. `huge` is
 * unbounded.
 */
const UPPER_BOUNDS: readonly (readonly [Bucket, number])[] = [
	["tiny", 350],
	["small", 1800],
	["medium", 7000],
	["large", 24000],
];

export function bucketOf(tokens: number): Bucket {
	for (const [bucket, below] of UPPER_BOUNDS) if (tokens < below) return bucket;
	return "huge";
}

