import { describe, expect, test } from "bun:test";

import { weighted } from "./budget-table.ts";

describe("weighted", () => {
	test("weights each sample size by its bucket, keeping order", () => {
		expect(weighted([120, 90, 2400, 400, 8000])).toEqual([60, 45, 3000, 400, 12000]);
	});

	test("a huge size gets the huge weight", () => {
		expect(weighted([30000])).toEqual([67500]);
	});

	test("each threshold switches to the next bucket's weight", () => {
		expect(weighted([349, 350, 1799, 1800, 6999, 7000, 23999, 24000])).toEqual([
			174.5, 350, 1799, 2250, 8748.75, 10500, 35998.5, 54000,
		]);
	});

	test("an empty list gives an empty list", () => {
		expect(weighted([])).toEqual([]);
	});

	test("rejects a size that is not a finite, non-negative count", () => {
		expect(() => weighted([100, -1])).toThrow(RangeError);
		expect(() => weighted([Number.NaN])).toThrow(RangeError);
	});
});

