 * Each of `sizes` times its bucket's weight, in the same order. Not rounded.
 *
 * @throws {RangeError} when a size is negative, NaN or infinite.
 */
export function weighted(sizes: number[]): number[] {
	return sizes.map((size) => size * WEIGHT[bucketOf(size)]);
}

