import type { HarnessMessage } from "./messages.ts";
import { approximateTokens } from "./tokens.ts";
import { reconstructTurns } from "./turns.ts";

/** Size classes of a Turn by its estimated tokens, smallest first. */
export const BUCKETS = ["tiny", "small", "medium", "large", "huge"] as const;

export type Bucket = (typeof BUCKETS)[number];

/**
 * Exclusive upper bound of each bucket; its inclusive lower bound is the
 * previous bucket's upper bound. `huge` is unbounded.
 */
const BELOW: Record<Bucket, number> = {
	tiny: 350,
	small: 1800,
	medium: 7000,
	large: 24000,
	huge: Number.POSITIVE_INFINITY,
};

/**
 * The bucket a Turn of `tokens` estimated tokens falls in.
 *
 * @throws {RangeError} when `tokens` is negative, NaN or infinite.
 */
export function bucketOf(tokens: number): Bucket {
	if (!Number.isFinite(tokens) || tokens < 0) {
		throw new RangeError(`Turn size must be a finite, non-negative token count; got ${tokens}`);
	}
	return BUCKETS.find((bucket) => tokens < BELOW[bucket]) ?? "huge";
}

/**
 * The estimated tokens of each Turn in `messages`, in order, one entry per
 * Turn that `reconstructTurns` finds.
 *
 * Leading-Turn rule: messages before the first user prompt (a system prompt,
 * say) are grouped by `reconstructTurns` into a leading Turn that has no
 * prompt. That Turn is dropped, so its messages are not counted and every
 * returned size belongs to a Turn that opens with a user prompt. A user
 * prompt with empty text still opens a Turn and is kept.
 */
export function turnSizes(messages: HarnessMessage[]): number[] {
	const turns = reconstructTurns(messages);
	// Only the first Turn can open with something other than a user prompt.
	// Checked by role rather than by an empty `prompt`, which a user prompt
	// with no text also has.
	if (turns[0]?.messages[0]?.role !== "user") turns.shift();
	return turns.map((turn) => approximateTokens(turn.messages));
}

/**
 * How many of `sizes` fall in each bucket, largest bucket first. Every bucket
 * gets an entry, with count 0 when empty, except `huge`, which is left out
 * when no size falls in it.
 *
 * @throws {RangeError} when a size is negative, NaN or infinite.
 */
export function histogram(sizes: number[]): { bucket: Bucket; count: number }[] {
	const counts: Record<Bucket, number> = { tiny: 0, small: 0, medium: 0, large: 0, huge: 0 };
	for (const size of sizes) counts[bucketOf(size)] += 1;
	return [...BUCKETS]
		.reverse()
		.filter((bucket) => bucket !== "huge" || counts.huge > 0)
		.map((bucket) => ({ bucket, count: counts[bucket] }));
}

/** The plain sum of `sizes`; 0 for an empty list. */
export function totalOf(sizes: number[]): number {
	return sizes.reduce((total, size) => total + size, 0);
}

/** Multiplier applied to a Turn's size by its bucket. */
const WEIGHT: Record<Bucket, number> = {
	tiny: 0.5,
	small: 1,
	medium: 1.25,
	large: 1.5,
	huge: 2.25,
};

/**
 * Each of `sizes` times its bucket's weight, rounded to the nearest multiple
 * of 10 with halves rounding up, in the same order.
 *
 * @throws {RangeError} when a size is negative, NaN or infinite.
 */
export function weighted(sizes: number[]): number[] {
	return sizes.map((size) => Math.round((size * WEIGHT[bucketOf(size)]) / 10) * 10);
}

