import { describe, expect, test } from "bun:test";

import { bucketOf, formatCount, histogram, totalOf, turnSizes, type Bucket } from "./budget-table.ts";
import type { HarnessMessage } from "./messages.ts";
import { approximateTokens } from "./tokens.ts";

describe("bucketOf", () => {
	// Each boundary pair: the last size below it and the first size at it.
	test.each<[number, Bucket]>([
		[0, "tiny"],
		[349, "tiny"],
		[350, "small"],
		[1799, "small"],
		[1800, "medium"],
		[6999, "medium"],
		[7000, "large"],
		[23999, "large"],
		[24000, "huge"],
		[Number.MAX_SAFE_INTEGER, "huge"],
	])("%p tokens is %p", (tokens, bucket) => {
		expect(bucketOf(tokens)).toBe(bucket);
	});

	test("fractional sizes fall between the integer boundaries", () => {
		expect(bucketOf(349.5)).toBe("tiny");
		expect(bucketOf(23999.9)).toBe("large");
	});

	test.each([-1, -0.5, Number.NaN, Number.POSITIVE_INFINITY, Number.NEGATIVE_INFINITY])(
		"%p tokens throws a RangeError",
		(tokens) => {
			expect(() => bucketOf(tokens)).toThrow(RangeError);
		},
	);
});

describe("histogram", () => {
	test("counts the sample sizes per bucket, largest bucket first", () => {
		expect(histogram([120, 90, 2400, 400, 8000])).toEqual([
			{ bucket: "large", count: 1 },
			{ bucket: "medium", count: 1 },
			{ bucket: "small", count: 1 },
			{ bucket: "tiny", count: 2 },
		]);
	});

	test("with no huge size, empty buckets stay at 0 and huge is left out", () => {
		expect(histogram([23999, 0, 349])).toEqual([
			{ bucket: "large", count: 1 },
			{ bucket: "medium", count: 0 },
			{ bucket: "small", count: 0 },
			{ bucket: "tiny", count: 2 },
		]);
	});

	test("an empty list gives every bucket but huge at 0", () => {
		expect(histogram([])).toEqual([
			{ bucket: "large", count: 0 },
			{ bucket: "medium", count: 0 },
			{ bucket: "small", count: 0 },
			{ bucket: "tiny", count: 0 },
		]);
	});
});

describe("totalOf", () => {
	test("sums the sizes", () => {
		expect(totalOf([120, 90, 2400, 400, 8000])).toBe(11010);
	});

	test("an empty list totals 0", () => {
		expect(totalOf([])).toBe(0);
	});
});

describe("turnSizes", () => {
	// Contents differ in length so that a message counted in the wrong Turn,
	// or the leading message counted at all, changes the sizes.
	const leading: HarnessMessage = { role: "assistant", content: "x".repeat(400) };
	const firstPrompt: HarnessMessage = { role: "user", content: "first prompt" };
	const firstReply: HarnessMessage = { role: "assistant", content: "a".repeat(40) };
	const secondPrompt: HarnessMessage = { role: "user", content: "second" };
	const secondReply: HarnessMessage = { role: "assistant", content: "b".repeat(120) };
	const conversation = [leading, firstPrompt, firstReply, secondPrompt, secondReply];

	test("one size per prompted Turn, dropping the messages before the first prompt", () => {
		expect(turnSizes(conversation)).toEqual([
			approximateTokens([firstPrompt, firstReply]),
			approximateTokens([secondPrompt, secondReply]),
		]);
	});

	test("messages with no prompt at all give no sizes", () => {
		expect(turnSizes([leading])).toEqual([]);
	});
});

describe("formatCount", () => {
	test.each<[number, string]>([
		[0, "0"],
		[740, "740"],
		[999, "999"],
		[1000, "1.0k"],
		[1234, "1.2k"],
		[1250, "1.3k"],
		[12000, "12.0k"],
	])("%p is shown as %p", (n, shown) => {
		expect(formatCount(n)).toBe(shown);
	});
});

