// owner: OWN-9314
import { bucketTotals, formatCount, histogram, labelOf } from "./budget-table.ts";

/**
 * The budget table of Turns of `sizes` estimated tokens, one string per row:
 * the header, then one row per `histogram` entry in histogram order, giving
 * the bucket's label, its Turn count and its weighted total through
 * `formatCount`. Columns are joined by ` | ` with no padding.
 *
 * @throws {RangeError} when a size is negative, NaN or infinite.
 */
export function renderTable(sizes: number[]): string[] {
	const totals = bucketTotals(sizes);
	const rows = histogram(sizes).map(({ bucket, count }) =>
		[labelOf(bucket), String(count), formatCount(totals.get(bucket) ?? 0)].join(" | "),
	);
	return ["bucket | turns | weighted", ...rows];
}

