	test("the format note's example", () => {
		expect(summaryLine([400, 1000, 8000], 20000)).toBe(
			"turns=3 · total=9400 · used=47% · peak=large · over=0",
		);
	});

	test("no Turns gives peak=none and zeroes", () => {
		expect(summaryLine([], 20000)).toBe("turns=0 · total=0 · used=0% · peak=none · over=0");
	});

	test("over counts only sizes strictly above 9000; used may pass 100", () => {
		// 48001 / 10000 is 480.01%.
		expect(summaryLine([9000, 9001, 30000], 10000)).toBe(
			"turns=3 · total=48001 · used=480% · peak=huge · over=2",
		);
	});

	test("used rounds down, not to nearest", () => {
		// 200 / 300 is 66.67%.
		expect(summaryLine([200], 300)).toBe("turns=1 · total=200 · used=66% · peak=tiny · over=0");
	});

	test("peak is the largest bucket present wherever it sits in the list", () => {
		expect(summaryLine([24000, 100, 2000], 100000)).toBe(
			"turns=3 · total=26100 · used=26% · peak=huge · over=1",
		);
	});

	test("an exact percentage is not rounded down by float error", () => {
		// Dividing first gives 29 / 100 * 100 = 28.999999999999996.
		expect(summaryLine([29], 100)).toBe("turns=1 · total=29 · used=29% · peak=tiny · over=0");
	});

	test("an invalid size throws a RangeError", () => {
		expect(() => summaryLine([100, -1], 1000)).toThrow(RangeError);
	});

	test.each([0, -1, Number.NaN, Number.POSITIVE_INFINITY])("a budget of %p throws a RangeError", (budget) => {
		expect(() => summaryLine([100], budget)).toThrow(RangeError);
	});
});

