/** Turns larger than this many tokens (strictly) are counted as `over`. */
const OVER = 9000;

/**
 * One line summarising Turns of `sizes` tokens against `budget`, fields
 * joined by ` · `: `turns=`, the unweighted `total=`, `used=` (the total as a
 * percentage of `budget`, rounded down, possibly above 100), then the footer:
 * `peak=` (the largest bucket holding a Turn, `none` when there are none) and
 * `over=` (how many Turns exceed 9000 tokens).
 *
 * @throws {RangeError} when a size is negative, NaN or infinite, or `budget`
 * is not a finite positive number.
 */
export function summaryLine(sizes: number[], budget: number): string {
	if (!Number.isFinite(budget) || budget <= 0) {
		throw new RangeError(`Budget must be a finite, positive token count; got ${budget}`);
	}
	const buckets = new Set(sizes.map(bucketOf));
	const peak = [...BUCKETS].reverse().find((bucket) => buckets.has(bucket)) ?? "none";
	const total = totalOf(sizes);
	// Multiplied before dividing so that exact percentages stay exact.
	const used = Math.floor((total * 100) / budget);
	const over = sizes.filter((size) => size > OVER).length;
	return [
		`turns=${sizes.length}`,
		`total=${total}`,
		`used=${used}%`,
		`peak=${peak}`,
		`over=${over}`,
	].join(" · ");
}

/** Multiplier applied to a Turn's size by its bucket. */
const WEIGHT: Record<Bucket, number> = {
…
};
